parameters.jsCode:
// Get the extracted data from Firecrawl
const input = $input.first().json;
const loopUrl = $('Loop Over URLs1').item.json.url || '';

// If Firecrawl failed, return placeholder so the loop continues
if (!input.success || !input.data) {
  return [{
    json: {
      business_name: 'Scrape Failed',
      email: null,
      phone: 'Not available',
      address: null,
      location: 'Not available',
      url: loopUrl,
      company_description: 'Not available',
      email_verified: false,
      email_verification_state: 'failed'
    }
  }];
}

const extracted = input.data.extract || {};
const metadata = input.data.metadata || {};

// STRICT email validation
function isValidEmail(email) {
  if (!email || typeof email !== 'string') return false;
  const trimmed = email.trim().toLowerCase();
  if (trimmed.length < 5) return false;
  if (trimmed === 'null' || trimmed === '/contact') return false;
  const parts = trimmed.split('@');
  if (parts.length !== 2) return false;
  const [local, domain] = parts;
  if (!local || local.length === 0) return false;
  if (local.startsWith('.')) return false;
  if (local.endsWith('.')) return false;
  if (local.includes('..')) return false;
  if (!/^[a-z0-9._%+\-]+$/.test(local)) return false;
  if (!domain || domain.length < 3) return false;
  if (domain.startsWith('.')) return false;
  if (domain.startsWith('-')) return false;
  if (!domain.includes('.')) return false;
  if (!/^[a-z0-9.\-]+$/.test(domain)) return false;
  const tld = domain.split('.').pop();
  if (!tld || tld.length < 2) return false;
  return /^[a-z0-9._%+\-]+@[a-z0-9.\-]+\.[a-z]{2,}$/.test(trimmed);
}

function isValidPhone(phone) {
  if (!phone || phone === 'null' || phone === '/contact') return false;
  return /\d/.test(phone);
}

const business_name = extracted.businessName || metadata.title || 'Unknown Business';
const email = isValidEmail(extracted.email) ? extracted.email.trim() : null;
const phone = isValidPhone(extracted.phone) ? extracted.phone.trim() : 'Not available';
const address = (extracted.address && extracted.address !== 'null') ? extracted.address : null;
const location = (extracted.location && extracted.location !== 'null') ? extracted.location : 'Not available';
const url = metadata.sourceURL || metadata.url || loopUrl;

const company_description = extracted.companyDescription
  || metadata.ogDescription
  || metadata['og:description']
  || extracted.description
  || extracted.about
  || 'Not available';

return [{
  json: {
    business_name,
    email,
    phone,
    address,
    location,
    url,
    company_description,
    email_verified: false,
    email_verification_state: 'risky'
  }
}];

// Merge Reoon verification result with lead data
const leadData = $('Parse Lead Data1').item.json;
const reoon = $input.first().json || {};

// Reoon response: { status: "safe"|"valid"|"invalid"|"risky"|"unknown", is_deliverable: bool, ... }
const status = (reoon.status || '').toLowerCase();
const isDeliverable = reoon.is_deliverable === true;

// Consider "safe" and "valid" as verified; everything else as risky
const verified = status === 'safe' || status === 'valid' || isDeliverable;

return [{
  json: {
    ...leadData,
    email_verified: verified,
    email_verification_state: status || 'unknown',
    email_verification_score: reoon.score || 0
  }
}];

const leadData = $('Parse Lead Data1').item.json;

return [{
  json: {
    ...leadData,
    email_verified: false,
    email_verification_status: 'no_email',
    email_verification_score: 0
  }
}];

// Get the Firecrawl search results from the first input item
const inputData = $input.first().json;
const searchResults = inputData.data.web || [];

// ── LAYER 1: Domain blocklist (exact domain matches) ──
const blockedDomains = [
  // Social media
  'facebook.com', 'linkedin.com', 'twitter.com', 'instagram.com',
  'youtube.com', 'tiktok.com', 'pinterest.com', 'reddit.com',
  'threads.net', 'x.com',

  // Marketplaces
  'amazon.com', 'amazon.co.uk', 'amazon.de', 'amazon.fr',
  'ebay.com', 'etsy.com', 'alibaba.com', 'aliexpress.com',
  'walmart.com', 'target.com', 'temu' ,

  // Market research / report sites
  'grandviewresearch.com', 'factmr.com', 'datamintelligence.com',
  'persistencemarketresearch.com', 'mordorintelligence.com',
  'fortunebusinessinsights.com', 'marketsandmarkets.com',
  'alliedmarketresearch.com', 'transparencymarketresearch.com',
  'emergenresearch.com', 'verifiedmarketresearch.com',
  'coherentmarketinsights.com', 'futuremarketinsights.com',
  'imarcgroup.com', 'researchandmarkets.com', 'statista.com',
  'precedenceresearch.com', 'expertmarketresearch.com',
  'globalmarketinsights.com', 'zionmarketresearch.com',
  'reportsanddata.com', 'straitsresearch.com',
  'marketresearchfuture.com', 'technavio.com',
  'psmarketresearch.com', 'databridgemarketresearch.com',
  'skyquestt.com', 'thebrainyinsights.com',
  'sphericalinsights.com', 'custommarketinsights.com',

  // News / media / encyclopedias
  'wikipedia.org', 'britannica.com', 'bbc.com', 'cnn.com',
  'forbes.com', 'bloomberg.com', 'reuters.com',
  'nytimes.com', 'theguardian.com', 'huffpost.com',

  // Job sites
  'indeed.com', 'glassdoor.com', 'ziprecruiter.com',

  // Q&A / forums / dev
  'stackoverflow.com', 'github.com', 'quora.com',
  'medium.com', 'dev.to', 'w3schools.com',

  // Reviews / travel / classifieds
  'yelp.com', 'tripadvisor.com', 'booking.com',
  'airbnb.com', 'craigslist.org',

  // Generic directories
  'yellowpages.com', 'whitepages.com', 'manta.com',
  'bbb.org', 'dnb.com',
];

// ── LAYER 2: URL path patterns to exclude ──
const blockedUrlPatterns = [
  '/docs/', '/documentation/', '/blog/', '/news/',
  '/article/', '/press-release/', '/wiki/',
  '/report/', '/market-report/', '/research-report/',
  '/career', '/jobs/', '/job/','/journal' ,
];

// ── LAYER 3: Title/description keywords that indicate non-business pages ──
const blockedTitleKeywords = [
  'market size', 'market share', 'market report', 'market research',
  'market forecast', 'market analysis', 'market outlook',
  'market growth', 'market trends', 'market overview',
  'industry report', 'industry analysis', 'industry forecast',
  'cagr', 'compound annual growth',
  'billion by 20', 'million by 20',  // "USD 472.6 million by 2035"
  'market segmented', 'market is projected',
  'research report', 'forecast and outlook',
  'press release', 'news article', 'lifestyle' , 'lexurylifestyle' , 'lifestyle' , 
  'book', 'ebook'
];

// ── FILTER ──
const filteredResults = searchResults
  .filter(result => {
    const url = (result.url || '').toLowerCase();
    const title = (result.title || '').toLowerCase();
    const desc = (result.description || '').toLowerCase();
    const text = title + ' ' + desc;

    // Layer 1: Block known domains
    if (blockedDomains.some(d => url.includes(d))) return false;

    // Layer 2: Block URL path patterns
    if (blockedUrlPatterns.some(p => url.includes(p))) return false;

    // Layer 3: Block market research content by title/description
    if (blockedTitleKeywords.some(kw => text.includes(kw))) return false;

    // Must have a real URL
    if (!url || url.length < 10) return false;

    return true;
  })
  .map(result => ({
    json: {
      url: result.url,
      title: result.title || '',
      description: result.description || '',
      position: result.position || 0
    }
  }));

return filteredResults;

// Count valid leads (saved to valid leads sheet)
let validCount = 0;
let invalidCount = 0;

try {
  const validItems = $('Append row in sheet2').all();
  validCount = validItems.length;
} catch(e) {
  // Node may not have run
}

try {
  const invalidItems = $('Append row in sheet3').all();
  invalidCount = invalidItems.length;
} catch(e) {
  // Node may not have run
}

const total = validCount + invalidCount;

return [{
  json: {
    status: total > 0 ? "success" : "no_results",
    totalLeads: total,
    validLeads: validCount,
    invalidLeads: invalidCount,
    message: total > 0
      ? "Found " + total + " leads! (" + validCount + " valid, " + invalidCount + " invalid)"
      : "No leads found for your search.",
    processedAt: new Date().toISOString()
  }
}];

const items = $input.all();

return items.map(item => {
  const url = item.json.url || '';
  let companyName = '';

  // Method 1: Extract from /store/{name}/ pattern
  const storeMatch = url.match(/\/store\/([^\/\?]+)/);
  if (storeMatch) {
    companyName = storeMatch[1];
  }

  // Method 2: Extract domain-based name
  if (!companyName) {
    const domainMatch = url.match(/\/\/([^\/]+)/);
    if (domainMatch) {
      companyName = domainMatch[1].replace('www.', '');
    }
  }

  // Clean up
  companyName = companyName
    .replace(/\?.*$/, '')
    .replace(/-/g, ' ')
    .replace(/_/g, ' ')
    .replace(/\/$/, '')
    .trim()
    .toLowerCase();

  // FALLBACK: never let companyName be empty
  if (!companyName) {
    companyName = url || 'unknown-' + Math.random().toString(36).slice(2, 8);
  }

  return {
    json: {
      url: url,
      companyName: companyName,
      originalUrl: url
    }
  };
});

const items = $input.all();
return items.map(item => {
  const email = (item.json.email || '').trim().toLowerCase();
  const url = item.json.url || '';
  let domain = '';
  if (url) {
    try { domain = new URL(url).hostname.replace('www.', ''); } catch(e) {}
  }
  if (!email) {
    return { json: { ...item.json, email_status: 'missing', domain } };
  }
  const prefix = email.split('@')[0];
  const generic = ['info','contact','support','hello','admin','sales','help','office','team','enquiries','mail','general','service','enquiry','request','marketing','press','media','feedback','billing','accounts','hr','jobs','careers','webmaster','postmaster','noreply','no-reply','newsletter'];
  if (generic.includes(prefix)) {
    return { json: { ...item.json, email_status: 'generic', original_email: email, domain } };
  }
  return { json: { ...item.json, email_status: 'personal', domain } };
});

// ── Smart Query Variation Engine ──
// Instead of just appending "suppliers/distributors" to the same keywords,
// this generates truly different search angles to maximize unique leads.

const keywords = $('Webhook').item.json.body.keywords;
const location = $('Webhook').item.json.body.location;
const quantity = Number($('Webhook').item.json.body.quantity) || 100;
const numSearches = Math.ceil(quantity / 100);

// ── Step 1: Extract core terms from user keywords ──
// e.g. "botanical oil shops" → core = "botanical oil", businessType = "shops"
const words = keywords.toLowerCase().trim().split(/\s+/);
const businessWords = ['shops','shop','store','stores','supplier','suppliers',
  'distributor','distributors','company','companies','brand','brands',
  'manufacturer','manufacturers','retailer','retailers','wholesale',
  'vendor','vendors','seller','sellers','dealer','dealers','provider','providers'];
const coreParts = [];
const userBizType = [];
for (const w of words) {
  if (businessWords.includes(w)) userBizType.push(w);
  else coreParts.push(w);
}
const coreKeyword = coreParts.join(' '); // e.g. "botanical oil"

// ── Step 2: Related product/industry terms ──
// Maps common product keywords to related search angles
const relatedTerms = {
  'botanical': ['botanical oil', 'organic botanical', 'moroccan oil', 'natural oils', 'beauty oils', 'hair oil', 'cosmetic oils'],
  'oil': ['essential oils', 'carrier oils', 'natural oils', 'organic oils', 'beauty oils'],
  'cosmetic': ['beauty products', 'skincare', 'personal care', 'beauty brands', 'cosmetics ingredients'],
  'beauty': ['cosmetics', 'skincare brands', 'beauty products', 'personal care', 'natural beauty'],
  'skincare': ['skin care products', 'beauty brands', 'cosmetics', 'natural skincare', 'organic skincare'],
  'organic': ['natural products', 'eco-friendly', 'bio products', 'green beauty', 'organic ingredients'],
  'food': ['gourmet food', 'specialty food', 'organic food', 'natural food', 'food ingredients'],
  'supplement': ['dietary supplements', 'health products', 'nutraceuticals', 'vitamins', 'wellness products'],
};

// Find related terms based on the core keyword
const related = new Set();
for (const word of coreParts) {
  if (relatedTerms[word]) {
    relatedTerms[word].forEach(t => related.add(t));
  }
}

// ── Step 3: Business type variations ──
const bizTypes = ['suppliers', 'distributors', 'wholesale', 'manufacturers',
  'brands', 'companies', 'retailers', 'importers', 'exporters', 'vendors'];

// ── Step 4: Major cities for the location (geographic variation) ──
const citiesByCountry = {
  'united states': ['New York', 'Los Angeles', 'Chicago', 'Houston', 'Miami', 'San Francisco', 'Dallas', 'Seattle'],
  'usa': ['New York', 'Los Angeles', 'Chicago', 'Houston', 'Miami', 'San Francisco'],
  'united kingdom': ['London', 'Manchester', 'Birmingham', 'Edinburgh', 'Bristol', 'Leeds'],
  'uk': ['London', 'Manchester', 'Birmingham', 'Edinburgh', 'Bristol'],
  'germany': ['Berlin', 'Munich', 'Hamburg', 'Frankfurt', 'Cologne', 'Stuttgart'],
  'france': ['Paris', 'Lyon', 'Marseille', 'Toulouse', 'Bordeaux', 'Nice'],
  'spain': ['Madrid', 'Barcelona', 'Valencia', 'Seville', 'Bilbao', 'Malaga'],
  'italy': ['Milan', 'Rome', 'Turin', 'Florence', 'Naples', 'Bologna'],
  'canada': ['Toronto', 'Vancouver', 'Montreal', 'Calgary', 'Ottawa', 'Edmonton'],
  'netherlands': ['Amsterdam', 'Rotterdam', 'The Hague', 'Utrecht', 'Eindhoven'],
  'australia': ['Sydney', 'Melbourne', 'Brisbane', 'Perth', 'Adelaide'],
  'uae': ['Dubai', 'Abu Dhabi', 'Sharjah'],
  'saudi arabia': ['Riyadh', 'Jeddah', 'Dammam'],
  'morocco': ['Casablanca', 'Marrakech', 'Rabat', 'Fes', 'Tangier'],
  'india': ['Mumbai', 'Delhi', 'Bangalore', 'Chennai', 'Hyderabad', 'Pune'],
  'brazil': ['São Paulo', 'Rio de Janeiro', 'Belo Horizonte', 'Curitiba'],
  'japan': ['Tokyo', 'Osaka', 'Yokohama', 'Nagoya', 'Kyoto'],
  'south korea': ['Seoul', 'Busan', 'Incheon', 'Daegu'],
  'china': ['Shanghai', 'Beijing', 'Guangzhou', 'Shenzhen', 'Chengdu'],
};
const locLower = location.toLowerCase().trim();
const cities = citiesByCountry[locLower] || [];

// ── Step 5: Build diverse query pool ──
const queryPool = [];

// Strategy 1: Original query (always first)
queryPool.push(keywords + ' ' + location);

// Strategy 2: Core keyword + different business types + location
for (const biz of bizTypes) {
  if (!userBizType.includes(biz)) {
    queryPool.push(coreKeyword + ' ' + biz + ' ' + location);
  }
}

// Strategy 3: Related industry terms + location
for (const term of related) {
  queryPool.push(term + ' ' + location);
  // Also with business types
  queryPool.push(term + ' suppliers ' + location);
}

// Strategy 4: Core keyword + major cities (drill into specific cities)
for (const city of cities.slice(0, 4)) {
  queryPool.push(coreKeyword + ' ' + city);
  queryPool.push(coreKeyword + ' suppliers ' + city);
}

// Strategy 5: "buy [product] wholesale [location]" style queries
queryPool.push('buy ' + coreKeyword + ' wholesale ' + location);
queryPool.push(coreKeyword + ' B2B ' + location);
queryPool.push(coreKeyword + ' bulk ' + location);

// ── Step 6: Deduplicate and pick the best N queries ──
const seen = new Set();
const uniqueQueries = [];
for (const q of queryPool) {
  const normalized = q.toLowerCase().trim();
  if (!seen.has(normalized)) {
    seen.add(normalized);
    uniqueQueries.push(q);
  }
}

// Pick exactly numSearches queries
const selected = uniqueQueries.slice(0, numSearches);

// Build output items
const variations = selected.map((query, i) => ({
  json: {
    query,
    limit: Math.min(100, quantity - (i * 100)),
    searchIndex: i,
  }
}));

// Clear accumulated results for this run
const staticData = $getWorkflowStaticData('global');
staticData.accumulatedResults = [];

return variations;

// Accumulate Firecrawl results across loop iterations using static data
const staticData = $getWorkflowStaticData('global');
if (!staticData.accumulatedResults) staticData.accumulatedResults = [];

const results = $input.first().json;
if (results.data && results.data.web) {
  staticData.accumulatedResults.push(...results.data.web);
}

return [{ json: { accumulated: staticData.accumulatedResults.length } }];

// Read all accumulated Firecrawl results and deduplicate by URL
const staticData = $getWorkflowStaticData('global');
const allResults = staticData.accumulatedResults || [];

// Deduplicate by URL
const seen = new Set();
const unique = allResults.filter(r => {
  const url = (r.url || '').toLowerCase().replace(/\/+$/, '');
  if (!url || seen.has(url)) return false;
  seen.add(url);
  return true;
});

// Clean up static data
staticData.accumulatedResults = [];

// Return in the same format that Filter URLs1 expects
// (single item with data.web array)
return [{ json: { data: { web: unique } } }];

const body = $('Webhook').item.json.body;

// --- Location mapping ---
const locationMap = {
  'usa': 'United States', 'us': 'United States',
  'uk': 'United Kingdom', 'gb': 'United Kingdom',
  'uae': 'United Arab Emirates',
  'ksa': 'Saudi Arabia', 'sa': 'Saudi Arabia',
};
const rawLocation = (body.location || '').trim();
const location = locationMap[rawLocation.toLowerCase()] || rawLocation;

// --- Job titles ---
// Hardcoded decision-maker titles optimized for cosmetics/beauty ingredient sourcing
const defaultTitles = [
  'CEO', 'Founder', 'Co-Founder', 'Owner', 'Managing Director',
  'Procurement Manager', 'Purchasing Manager', 'Head of Purchasing', 'Sourcing Manager', 'Supply Chain Manager',
  'R&D Manager', 'Product Development Manager', 'Head of Product Development',
  'Cosmetic Chemist', 'Formulator', 'Head of R&D'
];
const jobTitles = body.jobTitles
  ? body.jobTitles.split(',').map(t => t.trim()).filter(Boolean)
  : defaultTitles;

// --- Keyword tag mapping ---
const rawIndustry = (body.industry || '').trim().toLowerCase();

const INDUSTRY_MAP = {
  'cosmetics & beauty':   ['cosmetics', 'beauty', 'personal care'],
  'cosmetics':            ['cosmetics', 'beauty', 'personal care'],
  'beauty':               ['beauty', 'cosmetics', 'personal care'],
  'skincare':             ['cosmetics', 'beauty', 'personal care', 'skin care'],
  'personal care':        ['personal care', 'cosmetics', 'beauty'],
  'spa & wellness':       ['wellness', 'health', 'beauty', 'spa'],
  'spa':                  ['wellness', 'beauty', 'spa'],
  'wellness':             ['wellness', 'health', 'beauty'],
  'health & supplements': ['health', 'wellness', 'dietary supplements', 'nutraceuticals'],
  'health and wellness':  ['health', 'wellness', 'beauty', 'spa'],
  'supplement':           ['dietary supplements', 'nutraceuticals', 'health', 'wellness'],
  'pharmaceuticals':      ['pharmaceuticals', 'health', 'wellness'],
  'pharmacy':             ['pharmaceuticals', 'health', 'wellness'],
  'food & beverage':      ['food production', 'food', 'beverages', 'health food'],
  'food and beverage':    ['food production', 'food', 'beverages', 'health food'],
  'food':                 ['food production', 'food', 'health food'],
  'hair care':            ['cosmetics', 'beauty', 'personal care', 'hair care'],
  'haircare':             ['cosmetics', 'beauty', 'personal care'],
  'natural products':     ['cosmetics', 'beauty', 'health', 'wellness', 'natural'],
  'cosmetic manufacturing': ['cosmetics', 'beauty', 'manufacturing', 'personal care'],
  'essential oils':       ['essential oils', 'aromatherapy', 'cosmetics', 'wellness'],
  'soap and cleaning compounds': ['cosmetics', 'personal care', 'beauty', 'soap'],
  'soap':                 ['cosmetics', 'personal care', 'beauty'],
  'organic':              ['cosmetics', 'beauty', 'health', 'wellness'],
  'natural':              ['cosmetics', 'beauty', 'wellness', 'health'],
  'packaging':            ['packaging', 'cosmetics', 'beauty'],
};

const industryTags = INDUSTRY_MAP[rawIndustry] || [rawIndustry];

// --- Additional keywords from free-text field ---
// These are comma-separated custom keywords from the form
const extraKeywords = (body.apolloKeywords || '')
  .split(',')
  .map(k => k.trim().toLowerCase())
  .filter(Boolean);

// Merge industry tags + extra keywords, remove duplicates
const allTags = [...new Set([...industryTags, ...extraKeywords])];

// --- Build Apollo search body ---
const searchBody = {
  per_page: Math.min(Number(body.quantity) || 25, 100),
  page: 1,
  organization_locations: [location],
  q_organization_keyword_tags: allTags,
  person_titles: jobTitles,
};

return [{ json: { searchBody, quantity: Number(body.quantity) || 25 } }];

const response = $input.first().json;
const people = response.people || [];

if (people.length === 0) {
  return [{ json: { _noResults: true } }];
}

// ──��� Industries to ALWAYS BLOCK ───────────────────────────────────────────
const BLOCKED = [
  'financial services', 'banking', 'accounting', 'insurance',
  'investment management', 'venture capital', 'private equity',
  'management consulting', 'business consulting', 'staffing and recruiting',
  'human resources', 'real estate', 'law practice', 'legal services',
  'information technology and services', 'computer software', 'internet',
  'telecommunications', 'construction', 'civil engineering', 'architecture',
  'education management', 'higher education', 'e-learning',
  'government administration', 'military', 'non-profit organization management',
  'market research', 'public relations', 'media production',
  'marketing and advertising',
];

function shouldBlock(person) {
  const org = person.organization || {};
  const industry = (org.industry || '').toLowerCase().trim();
  if (!industry) return false; // no industry label → let through, check at reveal stage
  return BLOCKED.some(b => industry.includes(b));
}

const filtered = people.filter(p => !shouldBlock(p));

const staticData = $getWorkflowStaticData('global');
staticData.apolloTotalResults = filtered.length;

if (filtered.length === 0) {
  return [{ json: { _noResults: true } }];
}

return filtered.map(p => ({
  json: {
    personId: p.id,
    firstName: p.first_name || '',
    title: p.title || '',
    hasEmail: p.has_email === true,
    hasPhone: p.has_direct_phone === 'Yes',
    orgName: (p.organization && p.organization.name) || '',
    orgIndustry: (p.organization && p.organization.industry) || '',
    _totalFromApollo: filtered.length,
  }
}));

const staticData = $getWorkflowStaticData('global');
const totalFromApollo = staticData.apolloTotalResults || 0;

return [{ json: {
  totalFromApollo,
  message: 'Apollo search complete',
} }];

const revealed = $input.first().json;
const person = revealed.person || {};
const org = person.organization || {};

const location = [org.city, org.state, org.country].filter(Boolean).join(', ');

let phone = '';
if (person.phone_numbers && person.phone_numbers.length > 0) {
  phone = person.phone_numbers[0].sanitized_number || person.phone_numbers[0].number || '';
} else if (org.phone) {
  phone = org.phone;
}

const description = org.short_description
  || (org.name + ' — ' + (org.industry || 'Company') + ' with ~' + (org.estimated_num_employees || '?') + ' employees');

const isVerified = person.email_status === 'verified';

// ── Business Category mapping from Apollo industry ──
const CATEGORY_MAP = [
  [['cosmetic','beauty','personal care','skin care','skincare','makeup'],  'Cosmetics & Skincare'],
  [['hair','salon','trichology'],                                           'Hair Care'],
  [['spa','wellness','massage','aromatherapy'],                             'Spa & Wellness'],
  [['health','fitness','gym','yoga'],                                       'Spa & Wellness'],
  [['natural','organic','botanical','herbal'],                              'Natural & Organic'],
  [['private label','contract manufactur','white label'],                   'Private Label / Mfg'],
  [['manufactur','packaging'],                                              'Private Label / Mfg'],
  [['wholesale','distribut','import','export'],                             'Wholesale / Distribution'],
  [['retail','e-commerce','ecommerce','shop','store'],                      'Retail / E-commerce'],
  [['food','beverage','drink','edible'],                                    'Food & Beverage'],
  [['pharma','nutraceut','supplement','biotech','drug'],                    'Pharma / Nutraceuticals'],
];
const rawIndustry = (org.industry || '').toLowerCase();
let businessCategory = 'Other';
for (let i = 0; i < CATEGORY_MAP.length; i++) {
  const [keywords, label] = CATEGORY_MAP[i];
  if (keywords.some(kw => rawIndustry.includes(kw))) { businessCategory = label; break; }
}

// ── Company Size mapping ──
const emp = org.estimated_num_employees || 0;
let companySize = '';
if (emp > 0) {
  companySize = emp <= 10 ? '1–10' : emp <= 50 ? '11–50' : emp <= 200 ? '51–200' : '200+';
}

// ── Source Query from webhook ──
const wb = $('Webhook').item.json.body || {};
const sourceQuery = [wb.keywords, wb.location].filter(Boolean).join(' — ');

return [{ json: {
  business_name: org.name || '',
  location: location,
  email: person.email || '',
  phone: phone,
  company_description: description,
  url: org.website_url || (org.primary_domain ? 'https://' + org.primary_domain : ''),
  contact_name: [person.first_name, person.last_name].filter(Boolean).join(' '),
  contact_title: person.title || '',
  email_verified: isVerified,
  email_status: person.email_status || 'unknown',
  companyDomain: org.primary_domain || '',
  business_category: businessCategory,
  company_size: companySize,
  source_query: sourceQuery,
  _totalFromApollo: $('Process Apollo Results').first().json._totalFromApollo || 0,
} }];
